"""Revise chapter 4 against the designated book, retaining existing anchors."""
import copy,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
RES=ROOT/'crane-app/CraneExam/Resources';BASE=ROOT/'tmp/ch4_revision_20261106'
before=json.loads((BASE/'textbook.json').read_text('utf-8'))
data=json.loads((RES/'textbook.json').read_text('utf-8'))
data['chapters'][3]=copy.deepcopy(before['chapters'][3]);chapter=data['chapters'][3]
sections={s['id']:s for s in chapter['sections']};olds={s['id']:copy.deepcopy(s['blocks']) for s in chapter['sections']}
def get(s,i):return next(b for b in sections[s]['blocks'] if b['id']==olds[s][i]['id'])
def patch(s,i,text=None,**attrs):
    b=get(s,i)
    if text is not None:b['text']=text
    b.update(attrs);return b
def replace(s,i,typ,**attrs):
    b=get(s,i);bid=b['id'];b.clear();b.update(id=bid,type=typ,**attrs);return b
def new(s,key,typ='p',**attrs):return dict(id=s+'-rev26-'+key,type=typ,**attrs)
def after(s,i,*blocks):
    seq=sections[s]['blocks'];at=seq.index(get(s,i));seq[at+1:at+1]=blocks
def table(s,key,rows,headers=('項目','意味・覚えること')):return new(s,key,'table',headers=list(headers),rows=rows)
def check(s,key,q,a):return [new(s,key+'-q',text=q,style='question'),new(s,key+'-a',text=a,style='answer')]
def figure(s,key,file,caption):return new(s,key,'svg',file=file,caption=caption,style='figure')
def reorder(s,indices):
    assert sorted(indices)==list(range(len(olds[s])))
    sections[s]['blocks']=[get(s,i) for i in indices]

