for s in chapter['sections']:
    at=next(i for i,b in enumerate(s['blocks']) if b.get('style')=='question')
    s['blocks'].insert(at,new(s['id'],'practice-heading','sub',text='確認問題：答えを見る前に考える'))
    for b in s['blocks']:
        if b['type'] in ('img','svg'):b['style']='figure'
        # Retain quiz terms only when the rewritten block actually contains them.
        if 'quizTerms' in b:
            body=' '.join([b.get('text','')]+b.get('items',[])+b.get('headers',[])+sum(b.get('rows',[]),[]))
            b['quizTerms']=[t for t in b['quizTerms'] if t in body]
